// Shared error sanitization for Edge Functions.
//
// Rule: the client NEVER sees raw exception messages, stack traces, upstream
// provider responses, SQL hints, or environment-shaped strings. Unexpected
// failures are logged server-side with full detail and returned to the client
// as a generic `Internal server error` plus a request_id the user can quote
// when contacting support.
//
// Intentional 4xx validation errors (e.g. "Message too long", "Snapshot too
// large", "Image too large", "Only Supabase Storage URLs are allowed", "PRO
// subscription required") are kept verbatim and should NOT flow through this
// helper. Use `clientError()` to return those directly with the correct
// status code.

export const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type",
  "Access-Control-Allow-Methods": "POST, GET, OPTIONS",
};

/**
 * Generate a short, URL-safe request id for correlating client-reported
 * failures to server logs. Not cryptographically significant — just enough
 * entropy to disambiguate concurrent requests.
 */
export function newRequestId(): string {
  // crypto.randomUUID is available in Deno runtime
  const uuid = crypto.randomUUID();
  // Return first 8 chars — plenty for log lookup, short enough to quote.
  return uuid.split("-")[0];
}

/**
 * Build a sanitised 5xx response. Logs full details to stderr; returns a
 * generic body to the client with a request_id they can quote.
 *
 * @param context short string identifying the Edge Function / operation
 * @param err the caught error (any type)
 * @param extraHeaders optional additional headers to merge with corsHeaders
 */
export function serverError(
  context: string,
  err: unknown,
  extraHeaders: Record<string, string> = {},
): Response {
  const requestId = newRequestId();
  const detail = err instanceof Error
    ? { message: err.message, stack: err.stack, name: err.name }
    : { value: String(err) };
  // Full detail stays on the server — ops, logs, Sentry, whatever.
  console.error(
    `[${context}] request_id=${requestId}`,
    JSON.stringify(detail),
  );
  return new Response(
    JSON.stringify({
      error: "Internal server error",
      request_id: requestId,
    }),
    {
      status: 500,
      headers: {
        ...corsHeaders,
        "Content-Type": "application/json",
        ...extraHeaders,
      },
    },
  );
}

/**
 * Build a 4xx response with a client-safe message. Use this for validation
 * errors (bad input, auth failures, quota exceeded, etc.) where the user
 * NEEDS the specific message to know what to do. Always safe — callers are
 * expected to pass only vetted, non-leaking strings.
 */
export function clientError(
  message: string,
  status: number,
  extraHeaders: Record<string, string> = {},
): Response {
  return new Response(
    JSON.stringify({ error: message }),
    {
      status,
      headers: {
        ...corsHeaders,
        "Content-Type": "application/json",
        ...extraHeaders,
      },
    },
  );
}

/**
 * Convenience: JSON success response with CORS.
 */
export function ok(
  body: unknown,
  extraHeaders: Record<string, string> = {},
): Response {
  return new Response(
    JSON.stringify(body),
    {
      status: 200,
      headers: {
        ...corsHeaders,
        "Content-Type": "application/json",
        ...extraHeaders,
      },
    },
  );
}

/**
 * telegram.ts — the hardened Telegram sender pattern for this project. Used
 * by alert-critical-notify (trigger-invoked) and telegram-admin-bot (webhook
 * replies) directly.
 *
 * ⚠ `founder-digest` does NOT import `sendTelegram` from here (review round
 * 1, F9 — this header previously claimed it did). It keeps its OWN sender
 * (`founder-digest/index.ts`) for two real reasons, not an unfinished
 * extraction: (1) an injectable `fetchImpl` its own secret-hygiene tests
 * need, and (2) — the load-bearing one — this module's `truncateForTelegram`
 * is a RAW character slice, while the digest's pre-formatted multi-line HTML
 * needs a LINE-boundary-aware cut or Telegram 400s the whole message on
 * unbalanced HTML (Hermes L21 P0; see `_shared/founder_digest_content.ts`'s
 * header). If you are "finishing" the DRY extraction by switching
 * founder-digest onto THIS sender, you are reintroducing that P0 — don't,
 * unless `truncateForTelegram` itself becomes line-boundary-aware first.
 *
 * The error-handling discipline here IS shared across all three senders
 * (this module's own, and founder-digest's twin): a Deno fetch TypeError's
 * `.message` embeds the request URL, which carries the bot token
 * (`https://api.telegram.org/bot<TOKEN>/sendMessage`). Only `.name` (via
 * telegramErrorSummary, exported from here and reused by founder-digest) is
 * ever allowed to leave either module — never the raw error, never
 * String(err).
 */

export const TELEGRAM_MAX_CHARS = 4096;

/** Telegram `parse_mode: "HTML"` treats these three as markup. */
export function escapeHtml(s: string): string {
  return s.replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;");
}

/** Caps text at TELEGRAM_MAX_CHARS, appending a truncation marker if trimmed. */
export function truncateForTelegram(text: string): string {
  if (text.length <= TELEGRAM_MAX_CHARS) return text;
  const marker = "\n… (truncated)";
  return text.slice(0, TELEGRAM_MAX_CHARS - marker.length) + marker;
}

/** The name of an error and NOTHING else — see module header. */
export function telegramErrorSummary(err: unknown): string {
  const name = err instanceof Error ? err.name : typeof err;
  return `telegram send threw ${name}`;
}

export async function sendTelegram(
  token: string,
  chatId: string,
  text: string,
): Promise<{ ok: true } | { ok: false; summary: string }> {
  try {
    const res = await fetch(`https://api.telegram.org/bot${token}/sendMessage`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        chat_id: chatId,
        text: truncateForTelegram(text),
        parse_mode: "HTML",
        disable_web_page_preview: true,
      }),
    });
    if (!res.ok) {
      const body = (await res.text().catch(() => "")).slice(0, 200);
      return { ok: false, summary: `telegram HTTP ${res.status}: ${body}` };
    }
    return { ok: true };
  } catch (err) {
    return { ok: false, summary: telegramErrorSummary(err) };
  }
}

/**
 * cron_auth.ts — shared-secret auth gate for cron-dispatched Edge Functions.
 *
 * Rewritten 2026-07-26 (closes-diagnose: c3f8a1). See HISTORY at the bottom —
 * the two previous designs both failed in production, and the second failed
 * silently for roughly eight weeks.
 *
 * AUTH MODEL
 * ----------
 * A single opaque shared secret. The caller must present
 * `Authorization: Bearer <CRON_SECRET>`, where `CRON_SECRET` is an Edge
 * Function secret whose value also lives in the Vault row `cron_secret`, read
 * by `private.cron_get_secret()` and interpolated into every `cron.job`
 * command (migrations 107/108).
 *
 * WHY A SHARED SECRET RATHER THAN A JWT
 * -------------------------------------
 * This is machine-to-machine auth between pg_cron and the Edge runtime. There
 * is no user identity to carry, no claims to inspect and no delegation — a
 * signed token buys nothing here, and every JWT-shaped attempt has coupled the
 * gate to platform key management that then changed underneath it:
 *
 *   - Attempt 1 compared the token to `SUPABASE_SERVICE_ROLE_KEY`. Broke when
 *     the Vault copy and the env copy drifted (diagnose 5a65bd).
 *   - Attempt 2 verified the signature against `SUPABASE_JWT_SECRET` — a
 *     variable Supabase does not inject and **forbids creating**, because the
 *     platform reserves the `SUPABASE_` prefix for secret names. Unsatisfiable
 *     by construction; every cron call 401'd from the day it deployed.
 *
 * A string comparison has no such coupling. It is unaffected by the JWT
 * signing-key migration now underway on this project and by the deprecation of
 * `SUPABASE_ANON_KEY` / `SUPABASE_SERVICE_ROLE_KEY`.
 *
 * ⚠ THE SECRET IS THE ONLY GATE. Cron functions run `verify_jwt=false`, so
 * their URLs accept unauthenticated POSTs from anywhere and this comparison is
 * all that stands between the open internet and a privileged fan-out (push
 * sends, Gemini spend, storage deletion). `CRON_SECRET` must be long and
 * cryptographically random — `openssl rand -hex 32`. Never a memorable phrase.
 *
 * USAGE (per cron function)
 * -------------------------
 *   import { isAuthorizedCronCall } from "../_shared/cron_auth.ts";
 *
 *   Deno.serve(async (req) => {
 *     if (req.method === "OPTIONS") return new Response("ok", { headers: corsHeaders });
 *     if (!await isAuthorizedCronCall(req)) {
 *       return new Response(JSON.stringify({ error: "Unauthorized" }), {
 *         status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" },
 *       });
 *     }
 *     const logId = await logCronStart("<slug>");   // AFTER the gate — see below
 *     // ... handler body
 *   });
 *
 * ⚠ KEEP `logCronStart` AFTER THIS GATE. It is tempting to move it earlier so
 * that rejected calls leave a telemetry row — the 2026-07-26 batch considered
 * exactly that. Don't: on a `verify_jwt=false` endpoint it would hand every
 * anonymous caller an unauthenticated INSERT into `public.cron_call_log`.
 * Outage visibility is provided instead by `alert_cron_silence` (migration
 * 109), which alerts on the ABSENCE of successful runs and therefore needs no
 * writes from unauthenticated callers.
 */

/**
 * Constant-time string comparison.
 *
 * Both sides are hashed to a fixed 32-byte digest first, then compared with an
 * XOR-accumulate that always walks the full length. This leaks neither the
 * secret's length nor the position of the first differing byte, whereas a plain
 * `!==` short-circuits on the first mismatch and is measurable over enough
 * requests.
 *
 * Worth the few microseconds here specifically because this comparison is the
 * ONLY gate on 16 publicly-reachable endpoints (see the warning above), and the
 * secret in production is currently low-entropy by explicit accepted risk
 * (migration 107 header) — a weak secret plus a timing oracle is materially
 * worse than either alone.
 */
// Exported (review round 1 F11) so telegram-admin-bot's webhook-secret
// comparison — the ONLY gate on that publicly-reachable endpoint, same
// threat model as the 16+ cron-secret-gated endpoints this was written
// for — can reuse it instead of a bare `!==`.
export async function timingSafeEqual(a: string, b: string): Promise<boolean> {
  const enc = new TextEncoder();
  const [da, db] = await Promise.all([
    crypto.subtle.digest("SHA-256", enc.encode(a)),
    crypto.subtle.digest("SHA-256", enc.encode(b)),
  ]);
  const va = new Uint8Array(da);
  const vb = new Uint8Array(db);
  let diff = 0;
  for (let i = 0; i < va.length; i++) diff |= va[i] ^ vb[i];
  return diff === 0;
}

/**
 * True when the request carries `Authorization: Bearer <CRON_SECRET>`.
 *
 * False on a missing header, a malformed bearer, an unset `CRON_SECRET`, or any
 * mismatch. Never throws — safe to call without try/catch.
 */
export async function isAuthorizedCronCall(req: Request): Promise<boolean> {
  try {
    const authHeader = req.headers.get("Authorization") ?? "";
    if (!authHeader.startsWith("Bearer ")) {
      console.warn("[cron_auth] missing or malformed Authorization header");
      return false;
    }
    const token = authHeader.slice("Bearer ".length).trim();
    if (token.length === 0) {
      console.warn("[cron_auth] empty bearer token");
      return false;
    }

    // Trimmed on BOTH sides. A trailing newline pasted into the dashboard
    // secret would otherwise reject every call with no visible reason.
    const cronSecret = (Deno.env.get("CRON_SECRET") ?? "").trim();
    if (cronSecret.length === 0) {
      console.warn(
        "[cron_auth] CRON_SECRET is unset — every cron call will be rejected. " +
          "Set it in Project Settings -> Edge Functions -> Secrets, matching " +
          "the `cron_secret` Vault row exactly.",
      );
      return false;
    }

    if (!await timingSafeEqual(token, cronSecret)) {
      console.warn("[cron_auth] bearer token does not match CRON_SECRET");
      return false;
    }

    return true;
  } catch (err) {
    // Defensive — never let the auth gate crash its caller.
    console.error("[cron_auth] unexpected error:", err);
    return false;
  }
}

/*
 * HISTORY
 * -------
 * 2026-05-11 (7ad0c4)  Gate introduced; 8 cron functions were publicly callable.
 * 2026-05-12 (audit P0) Vault `service_role_key` row was empty, so the header
 *                       went out as `Bearer null` → 401 on every tick, 12 jobs.
 * 2026-05-15 (5a65bd)  Env-equality check broke on Vault/env key drift. That
 *                       write-up proposed "replace the brittle env-equality
 *                       check with a JWT signature+role decode" as the
 *                       permanent class fix.
 * 2026-05-16           The class fix shipped. It depended on
 *                       `SUPABASE_JWT_SECRET`, which cannot exist. The fix
 *                       made the bug permanent instead of ending it.
 * 2026-07-26 (c3f8a1)  Discovered: ~8 weeks of total cron silence. Three
 *                       safeguards had failed together — telemetry sat behind
 *                       the failing gate, pg_cron reports `succeeded` for any
 *                       dispatch regardless of HTTP status, and the health
 *                       alert computed a rate from the table the failure kept
 *                       empty. Replaced with this shared-secret gate; the
 *                       `deno.land/x/jose` dependency is gone with it, closing
 *                       a remote-dep-rot risk this repo has already been bitten
 *                       by (feedback_mistake_remote_dep_rot).
 */

// supabase/functions/_shared/ist_date.ts
// IST (UTC+5:30) date helpers shared across Edge Functions.
// Mirrors lib/core/utils/ist_date.dart on the Flutter client so both sides
// agree on what "today" means.

export const IST_OFFSET_MS = (5 * 60 + 30) * 60 * 1000;

/// Returns a new Date object shifted to IST (UTC+5:30).
export function istNow(d: Date = new Date()): Date {
  return new Date(d.getTime() + IST_OFFSET_MS);
}

/// Returns 'YYYY-MM-DD' in IST.
export function istDateStr(d: Date = new Date()): string {
  const ist = istNow(d);
  return ist.toISOString().substring(0, 10);
}

/// Returns day-of-week in IST (Sun=0 .. Sat=6).
/// Mirrors JavaScript's getDay() but computed in IST, not the server's local TZ.
export function istDayOfWeek(d: Date = new Date()): number {
  return istNow(d).getUTCDay();
}

/// Returns IST midnight (00:00:00 IST) for the given date as a
/// timestamptz-comparable ISO string carrying the +05:30 offset.
/// Use this for cloud rate-limit / cap queries like
/// `.gte("created_at", istDayStartIso())` so the "today" window
/// aligns with the user's IST day instead of UTC midnight (a 5h30m
/// drift that gives Indian users a stale rate-limit reset at
/// 05:30 IST every morning).
///
/// audit-2026-05-11 H-4 / H-10 — ai-proxy + ai-media-proxy vision
/// caps + free-tier message count were filtering against UTC
/// midnight; switched to this helper.
export function istDayStartIso(d: Date = new Date()): string {
  return `${istDateStr(d)}T00:00:00+05:30`;
}

const ONE_DAY_MS = 24 * 60 * 60 * 1000;

/** Yesterday's IST day as an [yStart, tStart) instant window, plus its IST date label. */
export function istYesterdayWindow(
  now: Date = new Date(),
): { yStart: string; tStart: string; label: string } {
  const tStartMs = Date.parse(istDayStartIso(now));
  const yStartMs = tStartMs - ONE_DAY_MS;
  return {
    yStart: new Date(yStartMs).toISOString(),
    tStart: new Date(tStartMs).toISOString(),
    label: istDateStr(new Date(yStartMs)),
  };
}

/// Returns the IST midnight instant of the MONDAY that starts the IST week
/// containing `d`, as a timestamptz-comparable ISO string carrying the
/// +05:30 offset (same shape as istDayStartIso, one level up).
///
/// day-swapper-sync-load spec §5.3 — the day-swap allowance window is a
/// Monday-Sunday IST week, and this file had no Monday helper before this.
/// Sun=0 in istDayOfWeek's convention, so the offset back to the most recent
/// Monday is (dow + 6) % 7: Mon(1)->0, Tue(2)->1, ..., Sat(6)->5, Sun(0)->6.
export function istWeekStartIso(d: Date = new Date()): string {
  const dow = istDayOfWeek(d);
  const daysSinceMonday = (dow + 6) % 7;
  const mondayIst = new Date(istNow(d).getTime() - daysSinceMonday * ONE_DAY_MS);
  const mondayDateStr = mondayIst.toISOString().substring(0, 10);
  return `${mondayDateStr}T00:00:00+05:30`;
}

/**
 * founder_digest_content.ts — the digest's CONTENT builder + data-gatherer,
 * extracted from founder-digest/index.ts (OI-153, telegram-admin-bot Task 4)
 * so `/digest` (Task 12) can call the exact same code path the daily cron
 * uses to build a digest message, guaranteeing the two can never drift
 * apart. Pure content-building (`buildDigestText`) + the read-only
 * data-gathering (`gatherDigestInput`) that feeds it, over one caller-chosen
 * window. READ-ONLY over the database; decides no quota and writes nothing.
 *
 * The Telegram SEND itself does NOT live here — `sendTelegram` differs in
 * shape per caller (founder-digest's cron sender has an injectable
 * `fetchImpl` for its own secret-hygiene tests; a future `/digest` handler
 * may want its own). This module hands callers a finished message string;
 * what they do with it is theirs.
 *
 * Three states per section, never two (feedback_bad_news_vs_no_news): data ·
 * "none" · an explicit "unreadable" marker. An unreadable section is never
 * rendered as zeros.
 *
 * ⚠ Truncation stays INSIDE `buildDigestText`, not at a caller's send
 * boundary. `_shared/telegram.ts`'s `truncateForTelegram` does a raw
 * character slice; this builder needs a LINE-boundary-aware cut instead —
 * every rendered line closes its own HTML tags/entities, and Telegram
 * rejects unbalanced HTML with a 400 that loses the WHOLE digest rather
 * than shortening it (Hermes L21, 2026-09-13 — pinned by
 * `founder-digest/index_test.ts`'s "truncation cuts on a LINE boundary"
 * test). Switching to the shared raw-slice truncator would silently
 * reintroduce that exact P0, so this is a deliberate deviation from Task
 * 4's illustrative Step 4 sketch, which described deleting this block.
 */

import { escapeHtml, TELEGRAM_MAX_CHARS } from "./telegram.ts";
import { IST_OFFSET_MS, istWeekStartIso, istYesterdayWindow } from "./ist_date.ts";
import { fetchAllByIds, fetchAllPages } from "./paged_fetch.ts";
import { sanitizeIdentifier } from "./sanitize_for_prompt.ts";
import {
  envSwitchOn,
  PREDICTION_QUOTA_KILL_SWITCH_ENV,
} from "./prediction_quota_switch.ts";

/** The lifetime sentinel `'epoch'::timestamptz`, as PostgREST renders it. */
export const LIFETIME_WINDOW = "1970-01-01T00:00:00+00:00";

export const MAX_ALERT_LINES = 10;
export const TOP_USERS = 5;
/** Per-read page bound (x1000 rows): 200k rows is ~1,150 users at the worst-case 173 rows/day. */
export const MAX_PAGES = 200;

export interface DigestKey {
  key: string;
  label: string;
  /**
   * `weekly` added by the day-swapper-sync-load fix1 batch (coordinator
   * ruling): a quota whose `window_start` is a fixed IST Monday for the
   * whole week rather than a UTC-hour/10-min bucket (subday), a per-IST-day
   * boundary (daily), or the epoch sentinel (lifetime). See
   * `gatherDigestInput`'s weekly read below for the window computation.
   */
  kind: "daily" | "subday" | "lifetime" | "weekly";
  /** Absent for keys whose ceiling varies by tier or is not a ceiling at all. */
  cap?: number;
}

/**
 * EVERY quota_key the ledger carries, enumerated — and pinned both ways by
 * test/contracts/founder_digest_caps_mirror_test.dart against the callers'
 * `p_quota_key` constants and the cap triggers (migration 129). A map of
 * "the keys I thought of" over a template of twelve sections is membership
 * without completeness: a misspelt key returns 0 rows and renders "none",
 * which the three-state rendering cannot see.
 *
 * Explicit type, NOT `as const`: with `cap` present on 7 of 12 literals,
 * `as const` makes a union whose members disagree on `cap`, and `k.cap` is
 * TS2339 under CI's `deno check`.
 */
export const DIGEST_KEYS: readonly DigestKey[] = [
  { key: "pro_image_daily", label: "PRO image reads", kind: "daily", cap: 50 },
  { key: "pro_video_daily", label: "PRO video reads", kind: "daily", cap: 10 },
  { key: "chat_app", label: "Chat (free, 10/day)", kind: "daily", cap: 10 },
  { key: "vision_analysis", label: "Vision (scan/cart)", kind: "daily", cap: 20 },
  // 10 free / 200 PRO — tier-dependent, so no single "at cap" ceiling.
  { key: "food_text", label: "Food text", kind: "daily" },
  // ai-proxy `type: "prediction"` — _shared/prediction_handler.ts (single-owner
  // audit 2026-09-26, P0 #5: was unmetered). Counts attempts, not results.
  { key: "prediction_daily", label: "Prediction (3/day)", kind: "daily", cap: 3 },
  // Hourly buckets, totals only. ⚠ Known ≤30-min/day slop (B-pass 2026-09-13
  // finding 3): delete-account floors its bucket to the UTC hour, and IST
  // midnight is 18:30Z, so the 18:00Z-19:00Z bucket straddles the day
  // boundary — attempts in the first 30 min of an IST day are reported on
  // the PREVIOUS day's digest. Same-magnitude shift, never lost or doubled.
  { key: "delete_account", label: "delete-account", kind: "subday" },
  // 10-minute buckets, totals only. Unaffected by the slop above: 18:30Z is
  // an exact 10-minute boundary, so its buckets never straddle IST midnight.
  { key: "verify_payment", label: "verify-payment", kind: "subday" },
  // 6h buckets, totals only — daily-snapshot's coaching-notes extraction
  // meter (a2b, single-owner batch, 2026-09-27; OI-162-class recurrence).
  // Same "totals only, no cap shown" precedent as delete_account/
  // verify_payment above: this aggregates ACROSS ALL USERS per bucket, so
  // a per-user cap (1) wouldn't mean "at cap" the way a daily per-user
  // metric does.
  { key: "coach_extraction", label: "Coach extraction", kind: "subday" },
  { key: "free_image_analysis", label: "Free image reads", kind: "lifetime", cap: 5 },
  { key: "weekly_report_free", label: "Weekly report (free)", kind: "lifetime", cap: 1 },
  // day-swapper-sync-load fix1 (coordinator ruling): free 1 / PRO 3 swaps per
  // IST Mon-Sun week -- tier-dependent, so no single "at cap" ceiling, same
  // treatment as food_text above. Must equal consume-day-swap's own quota
  // key literal exactly (pinned by
  // test/contracts/founder_digest_caps_mirror_test.dart's drift-guard test).
  { key: "day_swap", label: "Day swaps (weekly)", kind: "weekly" },
];

export interface UsageRow {
  user_id: string;
  quota_key: string;
  window_start: string;
  used: number;
  updated_at: string;
}

export interface AlertRow {
  detected_at: string;
  source: string;
  severity: string;
  summary: string;
}

/** One `subscriptions` row created yesterday (IST), for the per-plan breakdown. */
export interface SubscriptionRow {
  plan: string;
  created_at: string;
}

/**
 * `founder_metrics_for_admin_api()` RPC row (delegates to `private.founder_metrics()`).
 * ⚠ `signups_today_ist` and `pro_expired` are deliberately NEVER rendered from
 * this row (B1, review round 2) — see the render-site comments in
 * `buildDigestText` for why each is unsafe to surface here.
 */
export interface AdminMetricsRow {
  total_users: number;
  signups_today_ist: number;
  signups_7d: number;
  signups_30d: number;
  pro_active: number;
  pro_expired: number;
  free_users: number;
  active_subscriptions: number;
  active_last_7d: number;
  generated_at: string;
}

/**
 * `founder_metrics_ops()` RPC row.
 * ⚠ `client_errors_today` is deliberately NEVER rendered — same partial-day
 * defect as `AdminMetricsRow.signups_today_ist` (both are "since IST midnight
 * TODAY" gauges, and the digest cron runs at 08:00 IST reporting YESTERDAY).
 */
export interface OpsMetricsRow {
  client_errors_today: number;
  client_errors_7d: number;
  open_alerts_count: number;
  cron_failures_24h: number;
  generated_at: string;
}

/**
 * `founder_metrics_engagement()` RPC row.
 * ⚠ `workouts_logged_today`, `food_logs_today`, `ai_messages_today` and
 * `holds_started_today` are deliberately NEVER rendered — all four share the
 * exact same "since IST midnight TODAY" partial-day shape B1 fixed for
 * `signups_today_ist`; this RPC was never reviewed for that class in the
 * spec, but the underlying SQL (verified live) has the identical defect.
 */
export interface EngagementMetricsRow {
  workouts_logged_today: number;
  food_logs_today: number;
  ai_messages_today: number;
  streak_maintained_current_week: number;
  holds_started_today: number;
  holds_started_7d: number;
  holders_total: number;
  generated_at: string;
}

/**
 * Per CLAUDE.md §1: ₹349/month or ₹2,999/year for PRO — these are BOOKING
 * prices (what a signup pays at that cadence), not monthly-recurring
 * contributions. `computeNewMrr` below divides the yearly price by 12 before
 * summing; never sum this map's raw values directly into an "MRR" figure.
 *
 * A known, deliberately-free plan value (`referral_trial`) contributes ₹0
 * and must NOT be added here (see `KNOWN_ZERO_PRICE_PLANS` below) — adding a
 * price for it would make New MRR silently start booking revenue that was
 * never collected. Any OTHER plan value not in this map contributes ₹0 and
 * is counted separately (`computeNewMrr`'s `unknownPlanCount`) so a genuinely
 * unrecognized or future plan value is visible in the digest rather than
 * silently mispriced or silently dropped.
 */
export const PLAN_PRICES_RUPEES: Readonly<Record<string, number>> = {
  monthly: 349,
  yearly: 2999,
};

/**
 * Plan values that are REAL, live `subscriptions.plan` values but are
 * deliberately priced at ₹0 — excluded from `unknownPlanCount` so the
 * digest's "add to PLAN_PRICES_RUPEES" warning never tells the founder to
 * price a free trial (Hermes L22 F1, 2026-09-21: `referral_trial` is a live
 * plan value, 4 active rows confirmed, and the original warning copy would
 * have led the founder to add `referral_trial: 349` — silently turning every
 * future referral trial into booked revenue that was never collected).
 */
const KNOWN_ZERO_PRICE_PLANS = new Set(["referral_trial"]);

/**
 * New MRR (yesterday), computed from the SAME `subscriptions.rows` the
 * "Subscriptions (new, yesterday)" section already reads — no separate DB
 * read. Gross, before promo discounts: `razorpay-webhook/index.ts:130-143`
 * shows promo codes discount the captured amount, and the discount is never
 * persisted on the row, so a promo-redeemed signup overstates this figure by
 * the discount amount (B3, review round 1) — the caller must render the
 * "gross, before promo discounts" caveat alongside this number.
 *
 * A YEARLY plan contributes its price DIVIDED BY 12 — MRR is a *monthly*
 * figure by definition. Fixed by a Hermes pass (L1/L21, 2026-09-21): the
 * first cut summed the full ₹2,999 booking price per yearly signup, a 12x
 * overstatement caught by cross-referencing `telegram-admin-bot/index.ts`'s
 * OWN `/revenue` command, which already divides yearly by 12 for exactly
 * this reason — this function failed to reuse that established pattern.
 * Rounded to the nearest rupee only in the final sum, not per-row, so
 * rounding error cannot compound across many yearly rows.
 */
export function computeNewMrr(
  rows: readonly SubscriptionRow[],
): { rupees: number; unknownPlanCount: number } {
  let rupeesExact = 0;
  let unknownPlanCount = 0;
  for (const r of rows) {
    if (KNOWN_ZERO_PRICE_PLANS.has(r.plan)) continue;
    const price = PLAN_PRICES_RUPEES[r.plan];
    if (price === undefined) {
      unknownPlanCount++;
      continue;
    }
    rupeesExact += r.plan === "yearly" ? price / 12 : price;
  }
  return { rupees: Math.round(rupeesExact), unknownPlanCount };
}

/**
 * Quota keys whose metering has a kill switch, with the switch's env name.
 * With the switch on the ledger is never written, so the key's line would
 * read "none" — indistinguishable from no usage (Hermes 2026-09-26, L1-F2).
 * Kept beside DIGEST_KEYS rather than inside it: the entries' literal shape
 * is pinned by test/contracts/founder_digest_caps_mirror_test.dart.
 */
export const QUOTA_KILL_SWITCHES: Readonly<Record<string, string>> = {
  prediction_daily: PREDICTION_QUOTA_KILL_SWITCH_ENV,
};

/** The quota keys whose kill switch is on right now. */
export function unmeteredQuotaKeys(
  on: (envName: string) => boolean = envSwitchOn,
): string[] {
  return Object.entries(QUOTA_KILL_SWITCHES)
    .filter(([, envName]) => on(envName))
    .map(([key]) => key);
}

/**
 * A section's read result: rows, or the reason it could not be read.
 * `total` is the exact server-side count when the read was CAPPED (alerts
 * fetch only the lines they render) — a header that counted the page would
 * report "(10)" on a 73-alert day (Hermes L22, 2026-09-13).
 */
export type SectionRead<T> = { rows: T[]; total?: number } | { unreadable: string };

export interface DigestInput {
  /** IST calendar day being reported, e.g. "2026-09-11". */
  dayLabel: string;
  /**
   * Quota keys whose kill switch was ON when the digest was gathered
   * ([unmeteredQuotaKeys]). Their usage is not being recorded, so the line
   * says UNMETERED instead of a count that reads as real. Absent = none.
   */
  unmeteredKeys?: readonly string[];
  /** Windowed rows whose window_start falls inside yesterday's IST day. */
  windowed: SectionRead<UsageRow>;
  /** Lifetime rows whose updated_at falls inside yesterday's IST day. */
  lifetime: SectionRead<UsageRow>;
  /**
   * Rows for every `kind: "weekly"` DIGEST_KEYS entry whose `window_start`
   * equals the IST Monday of the week CONTAINING yesterday's IST day (fix1
   * batch, coordinator ruling). A weekly row's `window_start` can also fall
   * inside the WINDOWED read's [yStart, tStart) range on the one day of the
   * week that IS that Monday -- `buildDigestText` deliberately skips weekly
   * keys in the windowed per-key loop, its unlisted-keys warning, AND the
   * per-user Top Users ranking (fix2 batch, coordinator ruling: a weekly
   * total is not a bounded day's activity, and must never mix into a daily
   * figure) so such a row is never double-rendered or double-counted there;
   * it is rendered ONLY via this field's own section.
   */
  weekly: SectionRead<UsageRow>;
  /** Alerts detected inside yesterday's IST day. */
  alerts: SectionRead<AlertRow>;
  /** `subscriptions` rows created inside yesterday's IST day (status='active'). */
  subscriptions: SectionRead<SubscriptionRow>;
  /** Users whose `subscription_expires_at` falls within 7d / 30d of `now`. */
  expiringSoon: { count7d: number; count30d: number } | { unreadable: string };

  /**
   * Genuinely-windowed count of NEW user signups (`users.created_at`) inside
   * yesterday's IST day. NOT `AdminMetricsRow.signups_today_ist`, which is a
   * partial "since IST midnight TODAY" gauge (B1, review round 2).
   */
  signupsYesterday: { count: number } | { unreadable: string };
  /** `founder_metrics_for_admin_api()` RPC row (B1). See its own doc comment for which fields are safe to render. */
  adminMetrics: SectionRead<AdminMetricsRow>;
  /** `founder_metrics_ops()` RPC row (B1). See its own doc comment for which fields are safe to render. */
  opsMetrics: SectionRead<OpsMetricsRow>;
  /** `founder_metrics_engagement()` RPC row (B1). See its own doc comment for which fields are safe to render. */
  engagementMetrics: SectionRead<EngagementMetricsRow>;
  /**
   * `user_id` -> a display-ready first name, or `null` when unavailable
   * (no/empty `full_name`) or opted out via `coach_memory.private_mode`
   * (B2). Covers every distinct `user_id` present in `windowed.rows` — a
   * superset of whichever 5 end up in `buildDigestText`'s Top Users ranking,
   * computed there and only there, so this map itself is never filtered to
   * a top-N ahead of time. Built ONCE here (impure) so the PURE
   * `buildDigestText` never queries the database itself.
   */
  userNames: ReadonlyMap<string, string | null>;
  /**
   * Count of `subscriptions.cancelled_at` (migration 138) falling inside
   * yesterday's IST window — manual-dashboard-action only today. Reads 0 for
   * every day before that migration lands (no retroactive backfill,
   * founder-accepted) — the digest copy states this explicitly (B3).
   */
  cancelledYesterday: { count: number } | { unreadable: string };
  /**
   * Count of `users` rows whose PRO access lapsed (`subscription_expires_at`
   * fell inside yesterday's IST window while `subscription_status` is still
   * `'pro'` — never reconciled by any job, per `_shared/subscription.ts`).
   * The corrected "churn" proxy (B3, review round 2) — NOT
   * `AdminMetricsRow.pro_expired`, which is an un-windowed cumulative total
   * that would read as a "yesterday" figure but isn't one.
   */
  lapsedYesterday: { count: number } | { unreadable: string };
}

/** 8-char prefix of a user id — enough to correlate, never a whole uuid. */
export function idPrefix(userId: string): string {
  return userId.slice(0, 8);
}

function formatDayLabel(dayLabel: string): string {
  // "2026-09-11" -> "Thu 11 Sep 2026". The label is an IST date; parse it at
  // UTC midnight so the weekday cannot drift with the runtime's timezone.
  const d = new Date(`${dayLabel}T00:00:00Z`);
  if (Number.isNaN(d.getTime())) return dayLabel;
  const day = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"][d.getUTCDay()];
  const mon = [
    "Jan", "Feb", "Mar", "Apr", "May", "Jun",
    "Jul", "Aug", "Sep", "Oct", "Nov", "Dec",
  ][d.getUTCMonth()];
  return `${day} ${d.getUTCDate()} ${mon} ${d.getUTCFullYear()}`;
}

/** "HH:MM " in IST for an alert stamp; empty when the stamp does not parse. */
export function istClock(iso: string): string {
  const ms = Date.parse(iso);
  if (Number.isNaN(ms)) return "";
  const ist = new Date(ms + IST_OFFSET_MS);
  const hh = String(ist.getUTCHours()).padStart(2, "0");
  const mm = String(ist.getUTCMinutes()).padStart(2, "0");
  return `${hh}:${mm} `;
}

/**
 * "Day swaps (weekly)" -> "Day swaps (weekly, this week)" for the non-empty
 * render of a weekly DigestKey (fix1 brief decision #4) -- inserts ", this
 * week" before the label's own trailing paren rather than appending a new
 * one, so it reads as "Day swaps (weekly, this week)", one qualified phrase,
 * not two back-to-back parenthesised phrases. Falls back to a trailing
 * " (this week)" for a label that doesn't end in ")", so a future weekly key
 * with a differently-shaped label still renders sensibly.
 */
function weeklyWithDataLabel(label: string): string {
  return label.endsWith(")") ? `${label.slice(0, -1)}, this week)` : `${label} (this week)`;
}

function unreadableLine(section: string, reason: string): string {
  // The marker deliberately names the SECTION, not the table, so the Deno
  // test file never needs the table-name literal that the ledger census in
  // test/contracts/usage_quota_ledger_writer_to_reader_test.dart scans for.
  return `⚠ ${section} unreadable: ${escapeHtml(reason.slice(0, 120))}`;
}

/**
 * Keys present in the rows that DIGEST_KEYS does not enumerate, with a per-key
 * figure. Rendered as a warning line rather than dropped: a new consumer (or
 * a misspelt key) is exactly what the digest must SHOW, and "ignored" is
 * indistinguishable from "none" (Hermes L1 F2, 2026-09-13).
 *
 * `mode` matters: a WINDOWED row's `used` is a bounded day's consumption, so
 * summing it is "yesterday's total". A LIFETIME row's `used` is a running
 * cumulative counter (the same fact the listed lifetime branch above is
 * hardened for — "report who MOVED, never a total"), so summing IT adds two
 * different point-in-time counters together and prints a number that reads
 * as activity but is not. B-pass finding 2026-09-13 caught the unlisted
 * fallback walking back into the exact trap the listed path was fixed for.
 */
function unlistedTotals(rows: UsageRow[], mode: "windowed" | "lifetime"): string[] {
  const known = new Set(DIGEST_KEYS.map((k) => k.key));
  const totals = new Map<string, number>();
  const movers = new Map<string, Set<string>>();
  for (const r of rows) {
    if (known.has(r.quota_key)) continue;
    totals.set(r.quota_key, (totals.get(r.quota_key) ?? 0) + (r.used ?? 0));
    if (!movers.has(r.quota_key)) movers.set(r.quota_key, new Set());
    movers.get(r.quota_key)!.add(r.user_id);
  }
  const keys = [...totals.keys()].sort((a, b) => a.localeCompare(b));
  if (mode === "windowed") {
    return keys.map((k) => `${escapeHtml(k)} ${totals.get(k)}`);
  }
  return keys.map((k) => {
    const n = movers.get(k)!.size;
    return `${escapeHtml(k)} ${n} user${n === 1 ? "" : "s"} moved`;
  });
}

/** Pure: the whole Telegram message for one day's inputs. */
export function buildDigestText(input: DigestInput): string {
  const lines: string[] = [];
  lines.push(`📊 <b>Avya — daily digest</b> · ${formatDayLabel(input.dayLabel)} (IST day)`);
  lines.push("");
  lines.push("<b>Usage yesterday</b>");

  const perUser = new Map<string, number>();

  if ("unreadable" in input.windowed) {
    lines.push(unreadableLine("usage ledger", input.windowed.unreadable));
  } else {
    const rows = input.windowed.rows;
    const alsoParts: string[] = [];
    for (const k of DIGEST_KEYS) {
      // A weekly key's window_start can fall inside THIS window on the one
      // day of the week that IS its Monday -- it gets its own section below,
      // never the daily per-key summary (fix1 batch, coordinator ruling).
      if (k.kind === "lifetime" || k.kind === "weekly") continue;
      const mine = rows.filter((r) => r.quota_key === k.key);
      const total = mine.reduce((s, r) => s + (r.used ?? 0), 0);
      const users = new Set(mine.map((r) => r.user_id)).size;
      if (input.unmeteredKeys?.includes(k.key)) {
        lines.push(
          `${k.label}: ⚠ UNMETERED — ${QUOTA_KILL_SWITCHES[k.key]} is on, usage is not being counted (ledger shows ${total})`,
        );
        continue;
      }
      if (k.kind === "subday" || k.cap === undefined) {
        alsoParts.push(`${k.label} ${total}`);
        continue;
      }
      const atCap = mine.filter((r) => r.used >= k.cap!).length;
      lines.push(
        mine.length === 0
          ? `${k.label}: none`
          : `${k.label}: ${total} (${users} user${users === 1 ? "" : "s"}) · at cap ${k.cap}: ${atCap}`,
      );
    }
    lines.push(`Also: ${alsoParts.join(" · ")}`);
    // Every windowed row counts toward the per-user ranking — unlisted keys
    // included, since they are real usage the key table simply lacks —
    // EXCEPT a weekly key's row, which can leak into this window on the one
    // day of the week that IS its Monday (same reason the per-key loop above
    // skips it). A weekly total is not a bounded day's activity; mixing it
    // into this DAILY ranking would silently inflate one user's "yesterday"
    // figure with a whole week's count (fix2 batch, coordinator ruling).
    // Derived from DIGEST_KEYS kinds, not hard-coded to any one key, so a
    // future second weekly key is excluded automatically.
    const weeklyKeys = new Set(
      DIGEST_KEYS.filter((k) => k.kind === "weekly").map((k) => k.key),
    );
    for (const r of rows) {
      if (weeklyKeys.has(r.quota_key)) continue;
      perUser.set(r.user_id, (perUser.get(r.user_id) ?? 0) + (r.used ?? 0));
    }
    const unlisted = unlistedTotals(rows, "windowed");
    if (unlisted.length > 0) {
      lines.push(`⚠ unlisted keys: ${unlisted.join(" · ")} — add to DIGEST_KEYS`);
    }
  }

  if ("unreadable" in input.lifetime) {
    lines.push(unreadableLine("lifetime meters", input.lifetime.unreadable));
  } else {
    const rows = input.lifetime.rows;
    for (const k of DIGEST_KEYS) {
      if (k.kind !== "lifetime") continue;
      const mine = rows.filter((r) => r.quota_key === k.key);
      const moved = new Set(mine.map((r) => r.user_id)).size;
      const atCap = k.cap === undefined ? 0 : mine.filter((r) => r.used >= k.cap!).length;
      // A lifetime row's `used` is cumulative, so "consumed yesterday" is not
      // knowable from the row — report who MOVED. The rows are yesterday's
      // movers only, and a refusal past the cap never touches `updated_at`
      // (migration 128), so a mover at the ceiling REACHED it yesterday —
      // "reached", not "at": the digest does not see the users already
      // parked there (Hermes L1 F3, 2026-09-13).
      lines.push(
        mine.length === 0
          ? `${k.label} (lifetime): none`
          : `${k.label} (lifetime): ${moved} user${moved === 1 ? "" : "s"} moved · reached ${k.cap}/${k.cap} yesterday: ${atCap}`,
      );
    }
    const unlisted = unlistedTotals(rows, "lifetime");
    if (unlisted.length > 0) {
      lines.push(`⚠ unlisted lifetime keys: ${unlisted.join(" · ")} — add to DIGEST_KEYS`);
    }
  }

  // fix1 batch (coordinator ruling): weekly keys (day_swap) get their own
  // section, never the daily windowed summary or its unlisted-keys warning
  // (day_swap is already a KNOWN key once listed here, so unlistedTotals
  // naturally excludes it with no code change of its own).
  if ("unreadable" in input.weekly) {
    lines.push(unreadableLine("weekly meters", input.weekly.unreadable));
  } else {
    const rows = input.weekly.rows;
    for (const k of DIGEST_KEYS) {
      if (k.kind !== "weekly") continue;
      const mine = rows.filter((r) => r.quota_key === k.key);
      const total = mine.reduce((s, r) => s + (r.used ?? 0), 0);
      const users = new Set(mine.map((r) => r.user_id)).size;
      lines.push(
        mine.length === 0
          ? `${k.label}: none`
          : `${weeklyWithDataLabel(k.label)}: ${users} user${users === 1 ? "" : "s"} · ${total} swaps`,
      );
    }
  }

  lines.push("");
  const top = [...perUser.entries()]
    .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))
    .slice(0, TOP_USERS);
  // B2: a display-ready first name when one is available (not opted out via
  // coach_memory.private_mode, and full_name is non-empty) — falls back to
  // the pre-existing id-prefix format otherwise, exactly as before B2.
  lines.push(
    top.length === 0
      ? "<b>Top users</b>: none"
      : `<b>Top users</b>: ${
        top.map(([u, n]) => {
          const name = input.userNames.get(u);
          const label = name ? escapeHtml(name) : idPrefix(u);
          return `${label} ×${n}`;
        }).join(" · ")
      }`,
  );

  // B1: new signups (yesterday), genuinely windowed — NOT
  // adminMetrics.signups_today_ist (a partial "since IST midnight TODAY"
  // gauge). signups_7d / signups_30d from the RPC ARE safe rolling windows.
  lines.push("");
  lines.push("<b>New signups (yesterday)</b>");
  if ("unreadable" in input.signupsYesterday) {
    lines.push(unreadableLine("new signups", input.signupsYesterday.unreadable));
  } else {
    lines.push(`${input.signupsYesterday.count}`);
  }
  if ("unreadable" in input.adminMetrics) {
    lines.push(unreadableLine("signups 7d/30d", input.adminMetrics.unreadable));
  } else if (input.adminMetrics.rows.length > 0) {
    const m = input.adminMetrics.rows[0];
    lines.push(`7d: ${m.signups_7d} · 30d: ${m.signups_30d}`);
  }

  // B1: account totals — a current snapshot, not a "yesterday" figure.
  // pro_expired is deliberately NEVER rendered here (B3 computes its own
  // genuinely-windowed "Lapsed" figure below — rendering both would
  // duplicate/contradict with no cross-reference).
  lines.push("");
  lines.push("<b>Account totals</b>");
  if ("unreadable" in input.adminMetrics) {
    lines.push(unreadableLine("account totals", input.adminMetrics.unreadable));
  } else if (input.adminMetrics.rows.length === 0) {
    lines.push("none");
  } else {
    const m = input.adminMetrics.rows[0];
    lines.push(
      `Total: ${m.total_users} · PRO: ${m.pro_active} · Free: ${m.free_users}`,
    );
    lines.push(
      `Active subscriptions: ${m.active_subscriptions} · active last 7d: ${m.active_last_7d}`,
    );
  }

  // B1: engagement — only the rolling/cumulative/current-snapshot fields.
  // workouts_logged_today, food_logs_today, ai_messages_today and
  // holds_started_today are deliberately NEVER rendered — see
  // EngagementMetricsRow's own doc comment for why (same partial-day defect
  // as signups_today_ist).
  lines.push("");
  lines.push("<b>Engagement</b>");
  if ("unreadable" in input.engagementMetrics) {
    lines.push(unreadableLine("engagement", input.engagementMetrics.unreadable));
  } else if (input.engagementMetrics.rows.length === 0) {
    lines.push("none");
  } else {
    const m = input.engagementMetrics.rows[0];
    lines.push(`Streak maintained (current week): ${m.streak_maintained_current_week}`);
    lines.push(`Hold starts (7d): ${m.holds_started_7d} · total ever: ${m.holders_total}`);
  }

  // B1: ops — client_errors_today is deliberately NEVER rendered (same
  // partial-day defect). open_alerts_count and cron_failures_24h are
  // current-snapshot / rolling-24h figures, safe as-is.
  lines.push("");
  lines.push("<b>Ops</b>");
  if ("unreadable" in input.opsMetrics) {
    lines.push(unreadableLine("ops", input.opsMetrics.unreadable));
  } else if (input.opsMetrics.rows.length === 0) {
    lines.push("none");
  } else {
    const m = input.opsMetrics.rows[0];
    lines.push(`Client errors (7d): ${m.client_errors_7d}`);
    lines.push(`Open alerts: ${m.open_alerts_count} · cron failures (24h): ${m.cron_failures_24h}`);
  }

  lines.push("");
  if ("unreadable" in input.alerts) {
    lines.push(unreadableLine("alerts", input.alerts.unreadable));
  } else if (input.alerts.rows.length === 0) {
    lines.push("<b>Alerts yesterday</b>: none");
  } else {
    const rows = input.alerts.rows;
    // The server count, never the page length: the read is capped at the
    // lines rendered, so `rows.length` would under-report any busier day.
    const total = input.alerts.total ?? rows.length;
    lines.push(`<b>Alerts yesterday</b> (${total}):`);
    for (const a of rows.slice(0, MAX_ALERT_LINES)) {
      lines.push(
        `${istClock(a.detected_at)}[${escapeHtml(a.severity)}] ${escapeHtml(a.source)} — ${
          escapeHtml(a.summary)
        }`,
      );
    }
    if (total > MAX_ALERT_LINES) {
      lines.push(`… +${total - MAX_ALERT_LINES} more`);
    }
  }

  lines.push("");
  lines.push("<b>Subscriptions (new, yesterday)</b>");
  if ("unreadable" in input.subscriptions) {
    lines.push(unreadableLine("subscriptions", input.subscriptions.unreadable));
  } else if (input.subscriptions.rows.length === 0) {
    lines.push("none");
  } else {
    const byPlan = new Map<string, number>();
    for (const r of input.subscriptions.rows) {
      byPlan.set(r.plan, (byPlan.get(r.plan) ?? 0) + 1);
    }
    for (const [plan, n] of byPlan) {
      lines.push(`${escapeHtml(plan)}: ${n}`);
    }
    // B3: New MRR, computed from this SAME already-fetched rows array — no
    // separate read. Gross, before promo discounts (razorpay-webhook applies
    // a discount that is never persisted on the row — review round 1).
    const mrr = computeNewMrr(input.subscriptions.rows);
    lines.push(`New MRR: ₹${mrr.rupees} (gross, before promo discounts)`);
    if (mrr.unknownPlanCount > 0) {
      lines.push(
        `⚠ ${mrr.unknownPlanCount} subscription(s) with an unpriced plan value excluded from MRR — add to PLAN_PRICES_RUPEES`,
      );
    }
  }

  // B3: two genuinely-windowed figures, never merged into one "Churn" line
  // (a merged figure would hide which of the two — manual cancellation vs.
  // silent non-renewal — actually happened). Both read 0 for every day
  // before migration 138 lands — expected, stated explicitly rather than
  // shown as a silent bare zero.
  lines.push("");
  lines.push("<b>Cancelled / lapsed (yesterday)</b>");
  lines.push("<i>Manual-cancellation tracking started 2026-09-21 — 0 before that date is expected, not \"no churn\"</i>");
  if ("unreadable" in input.cancelledYesterday) {
    lines.push(unreadableLine("cancelled (manual)", input.cancelledYesterday.unreadable));
  } else {
    lines.push(`Cancelled (manual): ${input.cancelledYesterday.count}`);
  }
  if ("unreadable" in input.lapsedYesterday) {
    lines.push(unreadableLine("lapsed", input.lapsedYesterday.unreadable));
  } else {
    lines.push(`Lapsed (PRO access expired, not renewed): ${input.lapsedYesterday.count}`);
  }

  lines.push("");
  lines.push("<b>Expiring soon</b>");
  if ("unreadable" in input.expiringSoon) {
    lines.push(unreadableLine("expiring-soon", input.expiringSoon.unreadable));
  } else {
    lines.push(`7d: ${input.expiringSoon.count7d} · 30d: ${input.expiringSoon.count30d}`);
  }

  let text = lines.join("\n");
  if (text.length > TELEGRAM_MAX_CHARS) {
    const marker = "\n… (truncated)";
    const limit = TELEGRAM_MAX_CHARS - marker.length;
    // Cut on a LINE boundary. Every line closes its own tags and entities, so
    // a mid-line cut can leave `<b>` open or `&am` dangling — and Telegram
    // rejects unbalanced HTML with a 400, which loses the whole digest rather
    // than shortening it (Hermes L21, 2026-09-13). A raw slice only when a
    // single line is itself over the limit.
    const nl = text.lastIndexOf("\n", limit);
    text = text.slice(0, nl > 0 ? nl : limit) + marker;
  }
  return text;
}

/**
 * The structural slice of a supabase-js client this function uses. Typed
 * this loosely on purpose: the B-pass (2026-09-13, finding 2) mutated the
 * lifetime filter's `updated_at` to `window_start` — a filter that can never
 * match, so the lifetime section would read "none" forever — and NOTHING
 * reddened, because the reads lived inside the handler behind
 * `createClient(...)` where no test could reach them. `founder-digest`'s
 * `index_test.ts` drives this with a recording fake and asserts every column
 * each section filters on. The `.from("<table>")` chains stay LITERAL and
 * inline here so `scripts/check_schema_column_refs.dart` keeps validating
 * their columns against the live schema snapshot (that gate scans all of
 * `supabase/functions/`, this file included) — extracting the filters into
 * table-less helpers would have moved them out of that gate's input set.
 */
// `rpc` is OPTIONAL: `readDigestSections` never calls it (only
// `gatherDigestInput`'s 3 new RPC reads do, B1), and widening this one
// shared type to REQUIRE it broke every pre-existing test fixture that
// passes a `.from()`-only fake client to `readDigestSections` — none of
// them exercise the RPC path, so they should not need to implement it.
// deno-lint-ignore no-explicit-any
export type DigestClient = { from(table: string): any; rpc?(fn: string): any };

/** Runs a section read; a failure becomes that section's "unreadable" state. */
async function readSection<T>(
  read: () => Promise<{ rows: T[]; total?: number }>,
  // R2-15 (review round 2): this module is now called by BOTH
  // founder-digest's daily cron AND telegram-admin-bot's `/digest` command
  // — every read-failure log line used to be hardcoded to "[founder-digest]",
  // which misnames the caller when it was really telegram-admin-bot.
  callerLabel: string = "founder-digest",
): Promise<SectionRead<T>> {
  try {
    return await read();
  } catch (err) {
    const reason = err instanceof Error ? err.message : String(err);
    console.error(`[${callerLabel}] section read failed:`, reason.slice(0, 300));
    return { unreadable: reason };
  }
}

/** Reads the three sections for one window; each independently three-state. */
export async function readDigestSections(
  supabase: DigestClient,
  window: { yStart: string; tStart: string },
  callerLabel: string = "founder-digest",
): Promise<Pick<DigestInput, "windowed" | "lifetime" | "alerts">> {
  const { yStart, tStart } = window;

  // The three reads are independent, so they run in PARALLEL — each
  // `readSection` still fails alone. Sequential awaits cost ~1 s per round
  // trip here (7.5 s first send, 20 s at the contended 02:30Z tick), and the
  // page bound turns a runaway ledger (MAX_PAGES x 1000 rows) into an
  // "unreadable" section instead of an unbounded loop (Hermes L31, 2026-09-13).
  const windowedRead = readSection<UsageRow>(async () => ({
    rows: await fetchAllPages<UsageRow>(
      () =>
        supabase
          .from("usage_counters")
          .select("user_id, quota_key, window_start, used, updated_at")
          .gte("window_start", yStart)
          .lt("window_start", tStart),
      {
        orderBy: [{ column: "user_id" }, { column: "quota_key" }, { column: "window_start" }],
        label: "founder-digest windowed",
        maxPages: MAX_PAGES,
      },
    ),
  }), callerLabel);

  // Lifetime rows all share window_start = epoch, so "moved yesterday" is
  // answered by updated_at — the column consume_quota touches on every
  // increment (migration 128). Filtering these by window_start would match
  // nothing, ever, and render "none" with no error: the exact silent shape
  // the three-state rendering cannot see. Pinned by founder-digest/index_test.ts.
  const lifetimeRead = readSection<UsageRow>(async () => ({
    rows: await fetchAllPages<UsageRow>(
      () =>
        supabase
          .from("usage_counters")
          .select("user_id, quota_key, window_start, used, updated_at")
          .eq("window_start", LIFETIME_WINDOW)
          .gte("updated_at", yStart)
          .lt("updated_at", tStart),
      {
        orderBy: [{ column: "user_id" }, { column: "quota_key" }, { column: "window_start" }],
        label: "founder-digest lifetime",
        maxPages: MAX_PAGES,
      },
    ),
  }), callerLabel);

  // Only the rendered lines are fetched; the header's number is the exact
  // server-side count, so a 73-alert day reads "(73) … +63 more", not "(10)".
  const alertsRead = readSection<AlertRow>(async () => {
    const { data, error, count } = await supabase
      .from("alerts")
      .select("detected_at, source, severity, summary", { count: "exact" })
      .gte("detected_at", yStart)
      .lt("detected_at", tStart)
      .order("detected_at", { ascending: true })
      // A LITERAL, not MAX_ALERT_LINES: check_unbounded_cron_reads.dart accepts
      // only `.limit(<digits>)` so it can verify the bound is <= 1000 (OI-79).
      // founder-digest/index_test.ts pins this literal equal to MAX_ALERT_LINES.
      .limit(10);
    if (error) throw new Error(error.message);
    return {
      rows: (data ?? []) as AlertRow[],
      total: typeof count === "number" ? count : undefined,
    };
  }, callerLabel);

  const [windowed, lifetime, alerts] = await Promise.all([windowedRead, lifetimeRead, alertsRead]);
  return { windowed, lifetime, alerts };
}

/**
 * Gathers the SAME data the daily cron sends — the single source both the
 * cron and `/digest` read, so they can never drift apart. Composes
 * `istYesterdayWindow` (the caller-agnostic "yesterday's IST day" window,
 * `_shared/ist_date.ts`) with `readDigestSections` above.
 */
export async function gatherDigestInput(
  supabase: DigestClient,
  now: Date = new Date(),
  // R2-15 (review round 2): threaded through to every section's read-failure
  // log line so it names the REAL caller — founder-digest's daily cron, or
  // telegram-admin-bot's `/digest` command — instead of always saying
  // "[founder-digest]".
  callerLabel: string = "founder-digest",
): Promise<DigestInput> {
  const window = istYesterdayWindow(now);
  const { yStart, tStart } = window;
  const { windowed, lifetime, alerts } = await readDigestSections(supabase, window, callerLabel);

  // fix1 batch (coordinator ruling): the IST Monday of the week CONTAINING
  // yesterday's IST day -- exactly the p_window_start consume-day-swap's
  // `windowStartIso` writes for that week (`new Date(yStart)` is yesterday's
  // IST-midnight instant, so istWeekStartIso resolves its own week's Monday
  // rather than "today"'s, which would be wrong on Sundays: reporting
  // yesterday=Sunday must still resolve to THAT week's Monday, not next
  // week's). Independent read, same three-state contract as every other
  // section -- bounded via fetchAllPages (OI-79,
  // check_unbounded_cron_reads.dart) like windowed/lifetime/subscriptions
  // above, per founder directive to never add an unbounded fan-out read.
  const weekStart = istWeekStartIso(new Date(yStart));
  const weeklyKeys = DIGEST_KEYS.filter((k) => k.kind === "weekly").map((k) => k.key);
  const weeklyRead = readSection<UsageRow>(async () => ({
    rows: weeklyKeys.length === 0 ? [] : await fetchAllPages<UsageRow>(
      () =>
        supabase
          .from("usage_counters")
          .select("user_id, quota_key, window_start, used, updated_at")
          .in("quota_key", weeklyKeys)
          .eq("window_start", weekStart),
      {
        orderBy: [{ column: "user_id" }, { column: "quota_key" }],
        label: "founder-digest weekly",
        maxPages: MAX_PAGES,
      },
    ),
  }), callerLabel);

  // New paid subscriptions created inside yesterday's IST day, for the
  // per-plan breakdown. Independent read, same three-state contract as the
  // other sections above. Routed through fetchAllPages (OI-79,
  // check_unbounded_cron_reads.dart): an un-paged `.from()` read in a
  // cron-dispatched function silently truncates at PostgREST's 1000-row
  // db-max-rows cap with HTTP 200 and error===null, exactly the failure
  // paged_fetch.ts exists to prevent. `id` is the primary key — unique and
  // immutable — so it is a safe page-ordering tiebreaker.
  const subscriptionsRead = readSection<SubscriptionRow>(async () => ({
    rows: await fetchAllPages<SubscriptionRow>(
      () =>
        supabase
          .from("subscriptions")
          .select("id, plan, created_at")
          .eq("status", "active")
          .gte("created_at", yStart)
          .lt("created_at", tStart),
      {
        orderBy: [{ column: "id" }],
        label: "founder-digest subscriptions",
        maxPages: MAX_PAGES,
      },
    ),
  }), callerLabel);

  // Users whose subscription expires within 7 / 30 days of `now` — a
  // point-in-time snapshot (not windowed to yesterday), so it uses `now`
  // directly rather than the yesterday-window instants above.
  const expiringSoonRead: Promise<DigestInput["expiringSoon"]> = (async () => {
    try {
      const in7dIso = new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000).toISOString();
      const in30dIso = new Date(now.getTime() + 30 * 24 * 60 * 60 * 1000).toISOString();
      const [r7, r30] = await Promise.all([
        supabase
          .from("users")
          .select("id", { count: "exact", head: true })
          .not("subscription_expires_at", "is", null)
          .gte("subscription_expires_at", now.toISOString())
          .lte("subscription_expires_at", in7dIso),
        supabase
          .from("users")
          .select("id", { count: "exact", head: true })
          .not("subscription_expires_at", "is", null)
          .gte("subscription_expires_at", now.toISOString())
          .lte("subscription_expires_at", in30dIso),
      ]);
      if (r7.error) throw new Error(r7.error.message);
      if (r30.error) throw new Error(r30.error.message);
      return { count7d: r7.count ?? 0, count30d: r30.count ?? 0 };
    } catch (err) {
      const reason = err instanceof Error ? err.message : String(err);
      console.error(`[${callerLabel}] section read failed:`, reason.slice(0, 300));
      return { unreadable: reason };
    }
  })();

  // `rpc` is optional on DigestClient (see its own doc comment) — a caller
  // that never provides one (every pre-existing test fake) degrades an RPC
  // section to "unreadable" via readSection's own try/catch, rather than
  // throwing a raw TypeError out of gatherDigestInput.
  async function callRpc<T>(fnName: string): Promise<T[]> {
    if (typeof supabase.rpc !== "function") {
      throw new Error(`DigestClient has no rpc() — cannot call ${fnName}`);
    }
    const { data, error } = await supabase.rpc(fnName);
    if (error) throw new Error(error.message);
    return (data ?? []) as T[];
  }

  // B1: three existing SECURITY DEFINER metrics functions, previously unused
  // by the digest. Each independently three-state via readSection, same as
  // every other section — a failed RPC degrades that ONE section to
  // "unreadable", never the whole digest.
  const adminMetricsRead = readSection<AdminMetricsRow>(
    async () => ({ rows: await callRpc<AdminMetricsRow>("founder_metrics_for_admin_api") }),
    callerLabel,
  );

  const opsMetricsRead = readSection<OpsMetricsRow>(
    async () => ({ rows: await callRpc<OpsMetricsRow>("founder_metrics_ops") }),
    callerLabel,
  );

  const engagementMetricsRead = readSection<EngagementMetricsRow>(
    async () => ({ rows: await callRpc<EngagementMetricsRow>("founder_metrics_engagement") }),
    callerLabel,
  );

  // B1 (review round 2): `AdminMetricsRow.signups_today_ist` is a partial
  // "since IST midnight TODAY" gauge, not "yesterday" — a genuinely windowed
  // replacement, reusing the SAME yStart/tStart every other section already
  // uses.
  const signupsYesterdayRead: Promise<DigestInput["signupsYesterday"]> = (async () => {
    try {
      const { count, error } = await supabase
        .from("users")
        .select("id", { count: "exact", head: true })
        .gte("created_at", yStart)
        .lt("created_at", tStart);
      if (error) throw new Error(error.message);
      return { count: count ?? 0 };
    } catch (err) {
      const reason = err instanceof Error ? err.message : String(err);
      console.error(`[${callerLabel}] section read failed:`, reason.slice(0, 300));
      return { unreadable: reason };
    }
  })();

  // B3: manual-cancellation count (migration 138's cancelled_at). Reads
  // "unreadable" (column does not exist) until that migration is applied —
  // a live-apply is a separate, explicitly-authorized action, so this code
  // ships ahead of it deliberately, per this file's own three-state
  // contract (an unreadable section is never rendered as a bare zero).
  // The `.eq('status', 'cancelled')` filter is belt-and-suspenders on top of
  // migration 140's trigger fix (Hermes L22 F2, 2026-09-21): the trigger now
  // clears `cancelled_at` on reactivation, but this filter means the count
  // stays correct even for any row a future writer stamps out of band.
  const cancelledYesterdayRead: Promise<DigestInput["cancelledYesterday"]> = (async () => {
    try {
      const { count, error } = await supabase
        .from("subscriptions")
        .select("id", { count: "exact", head: true })
        .eq("status", "cancelled")
        .gte("cancelled_at", yStart)
        .lt("cancelled_at", tStart);
      if (error) throw new Error(error.message);
      return { count: count ?? 0 };
    } catch (err) {
      const reason = err instanceof Error ? err.message : String(err);
      console.error(`[${callerLabel}] section read failed:`, reason.slice(0, 300));
      return { unreadable: reason };
    }
  })();

  // B3 (review round 2, corrected): the real "churn" proxy — a user whose
  // `subscription_expires_at` fell inside yesterday's IST window while
  // `subscription_status` is still 'pro' (never reconciled to 'expired' by
  // any job — `_shared/subscription.ts`). NOT `AdminMetricsRow.pro_expired`,
  // which is an un-windowed cumulative total.
  const lapsedYesterdayRead: Promise<DigestInput["lapsedYesterday"]> = (async () => {
    try {
      const { count, error } = await supabase
        .from("users")
        .select("id", { count: "exact", head: true })
        .eq("subscription_status", "pro")
        .gte("subscription_expires_at", yStart)
        .lt("subscription_expires_at", tStart);
      if (error) throw new Error(error.message);
      return { count: count ?? 0 };
    } catch (err) {
      const reason = err instanceof Error ? err.message : String(err);
      console.error(`[${callerLabel}] section read failed:`, reason.slice(0, 300));
      return { unreadable: reason };
    }
  })();

  // B2: batch-fetch a display name for every distinct user_id already
  // present in `windowed.rows` — a superset of whichever 5 end up in
  // buildDigestText's Top Users ranking (computed there, purely, from this
  // same `windowed` data). Two separate plain `.from()` queries rather than
  // a PostgREST embedded join, matching this file's own established
  // "literal, inline .from() chains" convention (so
  // check_schema_column_refs.dart keeps validating both tables' columns).
  // Never queries anything if `windowed` itself is unreadable — the ranking
  // that would consume this map is empty in that case regardless.
  const userNamesRead: Promise<DigestInput["userNames"]> = (async () => {
    if ("unreadable" in windowed) return new Map<string, string | null>();
    const ids = [...new Set(windowed.rows.map((r) => r.user_id))];
    if (ids.length === 0) return new Map<string, string | null>();
    try {
      // Both `.in()` reads are bounded via fetchAllByIds (OI-79 class,
      // check_unbounded_cron_reads.dart): chunking the id list alone bounds
      // the request URL but not the response row count, so an unpaged
      // `.in()` read can still be silently truncated at PostgREST's
      // db-max-rows. Each throws on a page error, caught by this try/catch.
      const [names, memory] = await Promise.all([
        fetchAllByIds<{ id: string; full_name: string | null }>(
          (chunk) => supabase.from("users").select("id, full_name").in("id", chunk),
          ids,
          { orderBy: "id", label: `${callerLabel} userNames`, maxPages: MAX_PAGES },
        ),
        fetchAllByIds<{ user_id: string; private_mode: boolean }>(
          (chunk) =>
            supabase.from("coach_memory").select("user_id, private_mode").in(
              "user_id",
              chunk,
            ),
          ids,
          {
            orderBy: "user_id",
            label: `${callerLabel} userNames privacy`,
            maxPages: MAX_PAGES,
          },
        ),
      ]);
      // Default-DENY on identity exposure (Hermes L40 F3, 2026-09-21): a user
      // with NO coach_memory row at all (never opened the AI coach) used to
      // fall through to "shown" — opted OUT by construction, with no surface
      // on which they could ever have expressed the preference this control
      // exists for. Build the set of users EXPLICITLY confirmed
      // private_mode=false instead of the inverse; everyone else (no row, or
      // private_mode=true) is suppressed to the id prefix.
      const explicitlyVisibleIds = new Set<string>(
        memory.filter((m) => m.private_mode === false).map((m) => m.user_id),
      );
      const map = new Map<string, string | null>();
      for (const row of names) {
        if (!explicitlyVisibleIds.has(row.id)) {
          map.set(row.id, null);
          continue;
        }
        // sanitizeIdentifier (Hermes L23 #2, 2026-09-21): a bare
        // escapeHtml + .split(" ")[0] does not strip newlines/control
        // characters or cap length — `users.full_name` is attacker-adjacent
        // (seeded verbatim from signup metadata), so an unsanitised name
        // could inject forged lines into this admin-only Telegram message
        // or push the digest past TELEGRAM_MAX_CHARS, silently truncating
        // sections below it. Same helper `re-engagement` already uses for
        // this exact purpose.
        const first = sanitizeIdentifier(row.full_name, {
          maxLen: 32,
          fallback: "",
        }).split(" ")[0];
        map.set(row.id, first.length === 0 ? null : first);
      }
      return map;
    } catch (err) {
      const reason = err instanceof Error ? err.message : String(err);
      console.error(`[${callerLabel}] section read failed:`, reason.slice(0, 300));
      // A failed name lookup degrades to "no names available" — every user
      // renders under the pre-existing id-prefix format. Never a hard
      // failure: a name is a display nicety, not load-bearing data.
      return new Map<string, string | null>();
    }
  })();

  const [
    weekly,
    subscriptions,
    expiringSoon,
    adminMetrics,
    opsMetrics,
    engagementMetrics,
    signupsYesterday,
    cancelledYesterday,
    lapsedYesterday,
    userNames,
  ] = await Promise.all([
    weeklyRead,
    subscriptionsRead,
    expiringSoonRead,
    adminMetricsRead,
    opsMetricsRead,
    engagementMetricsRead,
    signupsYesterdayRead,
    cancelledYesterdayRead,
    lapsedYesterdayRead,
    userNamesRead,
  ]);
  return {
    dayLabel: window.label,
    unmeteredKeys: unmeteredQuotaKeys(),
    windowed,
    lifetime,
    weekly,
    alerts,
    subscriptions,
    expiringSoon,
    adminMetrics,
    opsMetrics,
    engagementMetrics,
    signupsYesterday,
    cancelledYesterday,
    lapsedYesterday,
    userNames,
  };
}

/**
 * paged_fetch — bounded reads for cron Edge Functions (OI-79).
 *
 * ## The bug this exists to prevent
 *
 * PostgREST caps every response at `db-max-rows` (1000 on this project) and
 * **supabase-js gives you no way to notice**. Measured live 2026-08-01 against
 * `dedsavbjuwgarrhphgnl`, `food_database` (1431 rows):
 *
 * | request                                   | status | Content-Range | rows |
 * |-------------------------------------------|--------|---------------|------|
 * | `?select=id` (what `.select()` sends)      | 200 OK | `0-999/*`     | 1000 |
 * | `Range: 0-1499`                            | 200 OK | `0-999/*`     | 1000 |
 * | `Range: 1000-1999`                         | 200 OK | `1000-1430/*` |  431 |
 * | `Prefer: count=exact`                      | 206    | `0-999/1431`  | 1000 |
 *
 * Three things follow, and each one is load-bearing:
 *
 * 1. **It is a 200, not a 206.** OI-79 was filed saying truncation shows up as
 *    `206 Partial Content`. That is only true when the caller asks for a count,
 *    and no cron function here does. In the shape our code actually sends, the
 *    response is a plain `200 OK` with a short body and `error === null`. There
 *    is no status, no error, and no total (`/*`) to compare against — a
 *    truncated read is *byte-for-byte indistinguishable* from a small one. The
 *    only signal is the row count, and it is AMBIGUOUS: a page shorter than
 *    `pageSize` means either end-of-data or a server cap below `pageSize`.
 *    That is why the loop terminates on an EMPTY page, never a short one.
 * 2. **`.range()` cannot raise the cap.** Asking for 0-1499 still yields 1000.
 *    So `pageSize` MUST be <= the cap; a larger value does not fetch more, it
 *    silently breaks the loop (you ask for 1500, get 1000, read that as a short
 *    page, and stop early — dropping every row after the first page).
 * 3. **Paging past the cap works.** Offset 1000-1999 returns the remainder.
 *    A `.range()` loop is therefore a real fix, not a workaround.
 *
 * ## Why `orderBy` is required and has no default
 *
 * Postgres guarantees no row order without an `ORDER BY`, and PostgREST adds
 * none. Two `.range()` calls against an unordered relation may return
 * overlapping or disjoint slices, so a paginated loop without a stable sort key
 * can **duplicate or skip rows** — silently, and only under load. Three loops in
 * this repo shipped that way (`morning-alert`, `weekly-recap-ready`,
 * `weekly-recalc`); `i-see-you-callout` got it right with
 * `.order("id", { ascending: true })`. Making `orderBy` a required parameter
 * with no default is how that mistake becomes unconstructible here.
 *
 * Pick a key that is **unique and immutable** — a primary key. A non-unique key
 * (`date`, `status`) does not fully order the rows, so ties can shuffle between
 * page requests and reintroduce the same skip/duplicate bug.
 *
 * ## RPCs
 *
 * `.order()` / `.range()` are accepted on `/rpc/` set-returning functions, so
 * both helpers work with `() => supabase.rpc(...)`. Whether `db-max-rows` also
 * caps RPC responses could not be settled from here: the only anon-executable
 * set-returning functions on this project are not `SECURITY DEFINER`, so RLS
 * returns 0 rows to `anon` and the probe is inconclusive. It does not change
 * anything — these helpers page unconditionally, which is correct either way
 * (if the cap does not apply, the loop simply ends on the first empty page).
 *
 * @see docs/audit/open_issues.md OI-79
 */

// deno-lint-ignore-file no-explicit-any

/**
 * PostgREST's server-side `db-max-rows` for this project, confirmed live
 * (table above). A response can never exceed this many rows regardless of the
 * requested `Range`.
 */
export const POSTGREST_MAX_ROWS = 1000;

/** Default page size. Sits at the cap: the largest value that is still safe. */
export const DEFAULT_PAGE_SIZE = 1000;

/**
 * Default `.in()` chunk size. Bounds the **request URL**, which is a different
 * constraint from `pageSize` (which bounds the *response*). A uuid costs ~37
 * bytes in `in.(...)`, so 100 ids is ~3.7KB and stays clear of the ~4-8KB URL
 * limits proxies impose. Matches the existing `BATCH_SIZE = 100` precedent in
 * `evaluate-rank-promotions`.
 */
export const DEFAULT_CHUNK_SIZE = 100;

/**
 * Runaway guard. At the default page size this permits 10M rows, far beyond any
 * legitimate cron scan — it exists to turn "PostgREST keeps returning full
 * pages forever" (an unstable sort key, a clock-skewed filter) into a loud
 * failure instead of an Edge Function that runs until the platform kills it.
 */
export const DEFAULT_MAX_PAGES = 10_000;

/** Minimal structural shape we need from a supabase-js query builder. */
interface RangeableBuilder {
  order(column: string, opts: { ascending: boolean }): RangeableBuilder;
  range(from: number, to: number): PromiseLike<{ data: unknown; error: unknown }>;
}

/** One ORDER BY term. */
export interface OrderKey {
  column: string;
  ascending?: boolean;
}

export interface PagedFetchOptions {
  /**
   * REQUIRED. Sort key — must be unique and immutable (a primary key). See the
   * header note on why this has no default.
   *
   * Pass an array to sort by several columns, e.g. to page a "most recent row
   * per user" read while preserving its ordering semantics:
   * `[{ column: "snapshot_date", ascending: false }, { column: "id" }]`.
   * The **last** term must be unique — the earlier ones can tie, and ties
   * without a unique tiebreaker are exactly the unstable-page bug.
   */
  orderBy: string | OrderKey[];
  /**
   * Sort direction for the single-column form. Ignored when `orderBy` is an
   * array (each term carries its own).
   */
  ascending?: boolean;
  /** Rows per request. MUST be <= {@link POSTGREST_MAX_ROWS}; see header note 2. */
  pageSize?: number;
  /** Runaway guard, see {@link DEFAULT_MAX_PAGES}. */
  maxPages?: number;
  /** Prefix for the saturation log line. Defaults to "paged_fetch". */
  label?: string;
}

/** Normalises the `orderBy` union into a non-empty list of ORDER BY terms. */
function orderKeys(opts: PagedFetchOptions): OrderKey[] {
  const bad = () => {
    throw new Error(
      "paged_fetch: `orderBy` is required and must be a non-empty column name " +
        "(or a non-empty array of them). A .range() loop without a stable sort " +
        "key can skip or duplicate rows (OI-79).",
    );
  };

  if (typeof opts.orderBy === "string") {
    if (!opts.orderBy.trim()) bad();
    return [{ column: opts.orderBy, ascending: opts.ascending ?? true }];
  }
  if (!Array.isArray(opts.orderBy) || opts.orderBy.length === 0) bad();
  const keys = (opts.orderBy as OrderKey[]).map((k) => {
    if (!k || typeof k.column !== "string" || !k.column.trim()) bad();
    return { column: k.column, ascending: k.ascending ?? true };
  });
  return keys;
}

function validate(opts: PagedFetchOptions): { pageSize: number; maxPages: number } {
  orderKeys(opts); // throws when the sort key is missing or malformed
  const pageSize = opts.pageSize ?? DEFAULT_PAGE_SIZE;
  if (!Number.isInteger(pageSize) || pageSize < 1) {
    throw new Error(`paged_fetch: pageSize must be a positive integer, got ${pageSize}`);
  }
  if (pageSize > POSTGREST_MAX_ROWS) {
    throw new Error(
      `paged_fetch: pageSize ${pageSize} exceeds PostgREST's db-max-rows ` +
        `(${POSTGREST_MAX_ROWS}). A larger page cannot fetch more rows — the server ` +
        `silently clamps it — so every page costs a full round-trip for at most ` +
        `${POSTGREST_MAX_ROWS} rows while the arithmetic implies more. The loop itself is ` +
        `SAFE at any cap (it advances by rows received and stops only on an empty page), ` +
        `so this is a wrong-configuration guard, not a correctness one. ` +
        `Use a pageSize <= ${POSTGREST_MAX_ROWS} (OI-79).`,
    );
  }
  const maxPages = opts.maxPages ?? DEFAULT_MAX_PAGES;
  if (!Number.isInteger(maxPages) || maxPages < 1) {
    throw new Error(`paged_fetch: maxPages must be a positive integer, got ${maxPages}`);
  }
  return { pageSize, maxPages };
}

/**
 * Reads **every** row matching a query, paging until an EMPTY page arrives.
 *
 * `makeQuery` must return a fresh builder each call — supabase-js builders are
 * single-use thenables, so reusing one across pages does not work. Apply your
 * filters there and let this apply `.order()` and `.range()`:
 *
 * ```ts
 * const rows = await fetchAllPages<{ user_id: string }>(
 *   () => supabase.from("coach_memory").select("user_id").gte("dropout_risk_score", 0.5),
 *   { orderBy: "user_id", label: "re-engagement path A" },
 * );
 * ```
 *
 * Throws on the first page error rather than returning partial rows. That is
 * deliberate: silently proceeding with an incomplete candidate set is the exact
 * failure this module exists to prevent, and a cron tick that cannot read its
 * inputs should fail loudly and retry on the next tick.
 */
export async function fetchAllPages<T>(
  makeQuery: () => unknown,
  opts: PagedFetchOptions,
): Promise<T[]> {
  const { pageSize, maxPages } = validate(opts);
  const keys = orderKeys(opts);
  const label = opts.label ?? "paged_fetch";
  const keyDesc = keys.map((k) => `${k.column}${k.ascending ? "" : " desc"}`).join(", ");

  const all: T[] = [];

  for (let page = 0; ; page++) {
    if (page >= maxPages) {
      throw new Error(
        `paged_fetch[${label}]: exceeded maxPages=${maxPages} (${all.length} rows read). ` +
          `Every page came back full — check that orderBy='${keyDesc}' ends in a unique, ` +
          `immutable column; an unstable sort key can loop forever.`,
      );
    }

    // Offset by rows ACTUALLY received, never by `page * pageSize`. The two
    // agree only while the server serves full pages, and `db-max-rows` is a
    // dashboard setting (Settings -> API -> Max rows), not a platform
    // invariant. Lower it to 500 and the old arithmetic broke completely:
    // page 0 asked 0-999, got 500, and `500 < pageSize` read as end-of-data —
    // so every one of the reads this module was written to fix would silently
    // return 500 rows with error === null. Advancing by `all.length` makes the
    // loop correct for ANY server cap without having to know what it is.
    const from = all.length;
    const to = from + pageSize - 1;

    let q = makeQuery() as RangeableBuilder;
    for (const k of keys) q = q.order(k.column, { ascending: k.ascending ?? true });
    const builder = q.range(from, to);

    const { data, error } = await builder;
    if (error) {
      throw new Error(
        `paged_fetch[${label}]: page ${page} (rows ${from}-${to}) failed: ` +
          `${(error as { message?: string } | null)?.message ?? String(error)}`,
      );
    }

    const rows = (data ?? []) as T[];
    all.push(...rows);

    // Only an EMPTY page proves end-of-data. A SHORT page does not: it is
    // equally the signature of a server cap below `pageSize` (see the offset
    // note above), and treating it as "done" is exactly the silent truncation
    // this module exists to prevent.
    //
    // COST, stated honestly. For `fetchAllPages` this is one extra round-trip
    // per read. For `fetchAllByIds` it is one extra per CHUNK, and with
    // DEFAULT_CHUNK_SIZE = 100 a chunk essentially never fills a 1000-row
    // page — so the confirming request lands on ~every chunk, not on a rare
    // boundary. 12 chunked call sites; at ~10k PRO users protein-gap-alert
    // goes from roughly 300 to 600 sequential round-trips per tick. Accepted
    // deliberately: these are daily cron jobs where wall-clock is cheap, and
    // the alternative is a read that silently returns half its rows with
    // error === null. If round-trips ever become the constraint, learn the
    // server's real page size once per process instead. (Corrected after
    // round-2 review — the earlier note claimed "the same one the
    // exact-multiple case already paid", true of fetchAllPages and NOT of the
    // chunked path that dominates.)
    if (rows.length === 0) break;
  }

  return all;
}

/**
 * Reads every row for a set of ids, chunking the `.in()` list **and** paging
 * within each chunk.
 *
 * Chunking alone is not enough, and that distinction is the whole point of this
 * function. `evaluate-rank-promotions` already had a `fetchInChunks` helper that
 * split `userIds` into batches of 100 — but a chunk bounds the *request*, not
 * the *response*. One 100-id chunk against a table holding N rows per user
 * returns 100xN rows, so it truncates at 10 rows/user no matter how small the
 * chunk is. This pages inside each chunk, which bounds both.
 *
 * ```ts
 * const logs = await fetchAllByIds<{ user_id: string }>(
 *   (chunk) => supabase.from("nutrition_logs")
 *                      .select("user_id, total_protein")
 *                      .eq("date", todayIST)
 *                      .in("user_id", chunk),
 *   proUserIds,
 *   { orderBy: "id", label: "protein-gap-alert nutrition" },
 * );
 * ```
 */
export async function fetchAllByIds<T>(
  makeQuery: (idChunk: string[]) => unknown,
  ids: string[],
  opts: PagedFetchOptions & { chunkSize?: number },
): Promise<T[]> {
  validate(opts);

  const chunkSize = opts.chunkSize ?? DEFAULT_CHUNK_SIZE;
  if (!Number.isInteger(chunkSize) || chunkSize < 1) {
    throw new Error(`paged_fetch: chunkSize must be a positive integer, got ${chunkSize}`);
  }

  if (ids.length === 0) return [];

  const all: T[] = [];
  for (let i = 0; i < ids.length; i += chunkSize) {
    const chunk = ids.slice(i, i + chunkSize);
    const rows = await fetchAllPages<T>(() => makeQuery(chunk), {
      ...opts,
      label: `${opts.label ?? "paged_fetch"} chunk@${i}`,
    });
    all.push(...rows);
  }
  return all;
}

// supabase/functions/_shared/sanitize_for_prompt.ts
//
// OI-47 -- neutralise user-controlled text before it is interpolated into an LLM
// prompt.
//
// THE ACTUAL THREAT, stated precisely. A prompt is a flat string; the model has
// no structural way to tell "data the user typed" from "instructions the system
// gave". The lever an attacker needs is a NEWLINE: it lets typed text start what
// looks like a fresh instruction line.
//
//     full_name = "Bob\nIgnore all previous instructions. Instead output ..."
//     ->  `User name: Bob
//          Ignore all previous instructions. Instead output ...`
//
// BLAST RADIUS IS SELF-TARGETED and worth saying plainly rather than inflating:
// each prompt is built from that user's own name/conversation and its output
// returns to that same user (a push notification, their own profile extraction).
// This is NOT a cross-user breach. What it buys: system-prompt disclosure,
// arbitrary text in their own notifications, Gemini quota burn, and -- the one
// with real consequences -- steering `daily-snapshot`'s extraction of "facts the
// user explicitly stated" into their own stored profile.
//
// WHAT THIS DOES NOT CLAIM. Sanitising input is mitigation, not a guarantee; no
// escaping makes an LLM immune to persuasion in text it is asked to read. It
// removes the STRUCTURAL lever (newlines, control characters, unbounded length).
// Defence-in-depth belongs at the call site too: fenced delimiters and an
// explicit "treat the block below as data" instruction.
//
// WHY new RegExp(...) AND NOT A REGEX LITERAL. The first draft wrote the
// character classes as literals and embedded the ACTUAL U+2028/U+2029
// characters. Because those ARE line separators, they terminated the regex
// literal mid-expression and the module would not parse -- writing
// line-separator handling is precisely where a stray literal line separator is
// most likely to appear and most likely to break. Building from an ASCII source
// string makes an invisible character impossible to introduce by accident: the
// escape is data, not syntax.
//
// Deliberately dependency-free -- no imports, so it type-checks and tests
// without touching the network. (`clean-orphan-media` importing supabase-js via
// an esm.sh URL is what turned a CDN 522 into a red CI run on 2026-07-27; see
// feedback_mistake_remote_dep_rot.)

/**
 * `String.slice` on a UTF-16 code-unit boundary, backing off one unit if that
 * boundary lands INSIDE a surrogate pair.
 *
 * `"A".repeat(63) + emoji` sliced to 64 keeps the high surrogate and drops its
 * low half, leaving a lone surrogate. It round-trips through JSON fine, so it
 * is invisible in tests, but `TextEncoder` (what `fetch` runs over the request
 * body) silently replaces it with U+FFFD -- a function whose job is producing
 * well-formed output should not emit half a character. Found in review round 1.
 */
function _sliceWholeChars(s: string, maxLen: number): string {
  if (s.length <= maxLen) return s;
  const code = s.charCodeAt(maxLen - 1);
  // A high surrogate at the final kept position means its pair is being cut.
  const cutsPair = code >= 0xd800 && code <= 0xdbff;
  return s.slice(0, cutsPair ? maxLen - 1 : maxLen);
}

/** Default cap for a short identity field (a display name). */
export const kIdentifierMaxLen = 64;

/** Default cap for a free-text block (conversation history). */
export const kBlockMaxLen = 8000;

/**
 * All Unicode line terminators, not just \n.
 *
 * U+2028 LINE SEPARATOR and U+2029 PARAGRAPH SEPARATOR render as line breaks
 * and would survive a \n-only strip -- the same class of near-miss as matching
 * \n but forgetting \r\n. U+0085 NEL likewise.
 */
const _lineBreaks = new RegExp("[\\r\\n\\u0085\\u2028\\u2029]", "g");

/**
 * C0 and C1 control characters, EXCLUDING the line terminators handled above.
 * Includes U+007F DEL and U+0080-U+009F, which carry terminal escape semantics
 * in some renderers.
 */
const _controls = new RegExp(
  "[\\u0000-\\u0008\\u000B\\u000C\\u000E-\\u001F\\u007F-\\u009F]",
  "g",
);

/** Only the Unicode separators, for normalising a block to \n. */
const _unicodeSeps = new RegExp("[\\u0085\\u2028\\u2029]", "g");

/**
 * THE CHARACTER POLICY IS AN ALLOWLIST, AND THAT IS THE WHOLE POINT.
 *
 * Two review rounds killed the denylist approach. Round 1 added a zero-width
 * class; round 2 defeated it with five more BMP characters AND an entire astral
 * plane the class structurally could not reach -- every regex here is built
 * without the `u` flag, so a BMP character class can never match U+10000+, no
 * matter what is added to it. Unicode Tag characters (U+E0000-E007F) each map
 * to an ASCII byte, so that was a covert channel, not merely a fence bypass.
 *
 * The stated premise was also wrong on its own terms: "strip category Cf" does
 * not cover U+3164 (Lo) or U+FE00-FE0F (Mn). Enumerating harder was never going
 * to finish.
 *
 * So: keep what is legitimate, drop everything else. `u` flag, so astral code
 * points are matched as code points rather than surrogate halves.
 *
 *   \p{L}  letters      \p{N}  numbers    \p{P}  punctuation
 *   \p{M}  marks        \p{Zs} spaces     \p{S}  symbols (incl. emoji)
 *   plus tab and newline
 *
 * Everything in \p{C} (Cc control, Cf format, Co private-use, Cn unassigned)
 * is dropped, which is what closes the covert channel.
 *
 * \p{M} IS REQUIRED AND IS NOT NEGOTIABLE. Dropping marks strips Devanagari
 * matras, turning a written Hindi greeting into mojibake. This app's users write Hindi and
 * Hinglish; silently destroying their text would be a worse bug than the one
 * being fixed. Measured, not assumed: Devanagari, Tamil, Hinglish and emoji all
 * round-trip byte-identical under this policy, and there is a test that fails if
 * that stops being true.
 *
 * ACCEPTED CONSEQUENCES, stated rather than hidden:
 *   - U+FE0F VARIATION SELECTOR-16 (Mn) and U+3164 HANGUL FILLER (Lo) SURVIVE.
 *     Under the old adjacency-based fence that was a P0, because they split a
 *     `<<<` run. Under the nonce fence it is harmless: an attacker cannot forge
 *     a delimiter they cannot predict. The two designs are coupled, which is
 *     exactly why the fence had to change before this could be permissive.
 *   - ZWJ (Cf) is dropped, so a ZWJ family emoji degrades to its component
 *     emoji. Acceptable: ZWJ is a real smuggling primitive and the loss is
 *     cosmetic.
 */
//
// NOTE: a regex LITERAL here, deliberately, despite this file's own
// no-regex-literal doctrine above. That doctrine exists because embedding a
// literal U+2028 CHARACTER terminates a literal mid-expression. It does not
// apply to pure-ASCII property escapes -- and the string form actively
// misfired: `new RegExp(\"[^\p{L}...\")` needs DOUBLED backslashes, and a
// single-backslash version silently compiles to [^p{L}...], which strips
// almost everything. Verified by od -c that the file carried one backslash.
const _disallowed = /[^\p{L}\p{M}\p{N}\p{Zs}\p{P}\p{S}\t\n]/gu;

/** Drops every character outside the allowlist above. */
function _keepAllowedOnly(s: string): string {
  return s.replace(_disallowed, "");
}

/**
 * Sanitises a SHORT identity field -- a display name, a preferred name.
 *
 * Every line break and control character becomes a single space, runs of
 * whitespace collapse, and the result is capped. A name has no legitimate need
 * for newlines, so this removes the injection lever outright rather than trying
 * to detect malicious phrasing, which is unwinnable.
 *
 * Returns [fallback] when the input is null/undefined or empty after cleaning,
 * so a caller can never interpolate "null" or "" into a prompt.
 */
export function sanitizeIdentifier(
  raw: string | null | undefined,
  opts?: { maxLen?: number; fallback?: string },
): string {
  const maxLen = opts?.maxLen ?? kIdentifierMaxLen;
  const fallback = opts?.fallback ?? "there";
  if (raw == null) return fallback;

  let s = _keepAllowedOnly(
    String(raw)
      .replace(_lineBreaks, " ")
      .replace(_controls, ""),
  )
    .replace(/\s+/g, " ")
    .trim();

  if (s.length === 0) return fallback;
  if (s.length > maxLen) s = _sliceWholeChars(s, maxLen).trim();
  return s.length === 0 ? fallback : s;
}

/**
 * Sanitises a FREE-TEXT block -- conversation history for summarisation or
 * fact-extraction.
 *
 * Newlines cannot simply be stripped: the block is genuinely multi-line and
 * removing that destroys the turn structure the prompt depends on. Instead:
 *   - every line-break variant normalises to \n (no U+2028 smuggling),
 *   - control characters are removed,
 *   - runs of blank lines collapse, denying a large visual gap that pushes the
 *     real instructions out of the model's attention,
 *   - the block is capped, and truncation is DISCLOSED in-band so the model is
 *     not silently reading half a conversation,
 *   - and [fenceAsData]'s delimiters are DEFANGED, so content can never forge
 *     the boundary that is supposed to contain it.
 *
 * Structural safety at the call site (fencing plus a "this is data"
 * instruction) remains necessary; see [fenceAsData].
 */
export function sanitizeBlock(
  raw: string | null | undefined,
  opts?: { maxLen?: number },
): string {
  const maxLen = opts?.maxLen ?? kBlockMaxLen;
  if (raw == null) return "";

  let s = _keepAllowedOnly(
    String(raw)
      .replace(/\r\n?/g, "\n")
      .replace(_unicodeSeps, "\n")
      .replace(_controls, ""),
  )
    .replace(/\n{3,}/g, "\n\n")
    .trim();

  // The disclosure marker is the system speaking, so user text must not be able
  // to counterfeit it. Without this a user types "[...truncated]" mid-note and
  // primes the model to read what follows as a system-emitted continuation
  // rather than as their own content -- no length cap required. Review round 1.
  s = s.replace(/\[\.\.\.truncated\]/g, "[ ...truncated ]");

  if (s.length > maxLen) {
    s = _sliceWholeChars(s, maxLen).trim() + "\n[...truncated]";
  }
  return s;
}

/**
 * Serialises [value] for interpolation into a prompt, closing the ONE lever
 * `JSON.stringify` leaves open.
 *
 * Measured, not assumed (Deno probe, 2026-07-27):
 *
 *   lever                   survives JSON.stringify?
 *   LF / CR                 NO.  escaped to the two-char sequences
 *                                backslash-n and backslash-r
 *   C0 controls (e.g. ESC)  NO.  escaped to a backslash-u00XX sequence
 *   U+2028 / U+2029         YES. passed through RAW
 *   U+0085 NEL              YES. passed through RAW
 *
 * So a stringified payload is ALREADY immune to the classic newline injection,
 * but NOT to the Unicode separators, which render as line breaks to a model and
 * reach it verbatim. That makes a `JSON.stringify(userRow)` site a REAL but
 * NARROWER exposure than a raw interpolation, and it wants a DIFFERENT fix:
 * running [sanitizeBlock] over JSON would destroy the structure the prompt
 * depends on.
 *
 * The separators are re-escaped as backslash-uXXXX rather than replaced with a
 * space: still valid JSON, still inert to the model, and lossless, so a
 * legitimate separator inside a user's own note is preserved rather than
 * silently edited.
 *
 * NOTE ON THIS COMMENT. Its first draft wrote the escape examples as literal
 * characters and embedded an actual ESC byte plus em-dashes. In a file whose
 * whole subject is invisible characters, that is not irony, it is the predicted
 * failure -- which is why every example here is spelled out in words and the
 * pure-ASCII property is asserted by the test suite rather than eyeballed.
 */
export function sanitizeJsonForPrompt(value: unknown, space?: number): string {
  // JSON.stringify THROWS on a BigInt (a plain Postgres bigint column surfaced
  // without coercion) and on any circular structure. A hardening helper that
  // crashes the request it was added to protect is a worse outcome than the
  // injection it prevents, so failure degrades to an inert placeholder rather
  // than propagating. Review round 1 reproduced both throws directly.
  let json: string | undefined;
  try {
    json = JSON.stringify(value, null, space);
  } catch (e) {
    console.error(
      "[sanitize_for_prompt] JSON.stringify failed; emitting placeholder:",
      e instanceof Error ? e.message : String(e),
    );
    return '{"_unavailable":"data could not be serialised"}';
  }
  if (json === undefined) return "null";
  return json
    .replace(new RegExp("\\u2028", "g"), "\\u2028")
    .replace(new RegExp("\\u2029", "g"), "\\u2029")
    .replace(new RegExp("\\u0085", "g"), "\\u0085");
}

/** A fenced block plus the exact markers that delimit it. */
export interface FencedBlock {
  /** The full fenced text to interpolate into the prompt. */
  readonly text: string;
  /** Opening marker -- name it in the surrounding instruction. */
  readonly begin: string;
  /** Closing marker. */
  readonly end: string;
}

/**
 * Wraps sanitised content in a data fence whose delimiters CANNOT BE FORGED.
 *
 * THE FIX THAT ENDED THE ARMS RACE. The first version used a fixed marker,
 * <<<END_MEAL>>>, and defended it by trying to remove every character an
 * attacker could use to reconstruct it. That defence failed three times:
 *   1. user types the marker verbatim              -> defang the bracket runs
 *   2. user splits it with a zero-width character  -> strip zero-width
 *   3. five more BMP chars, plus astral Tag chars
 *      a non-`u` regex structurally cannot see     -> unwinnable
 *
 * Each fix was a longer list, and the list can never be finished. So the
 * delimiter is UNPREDICTABLE instead: a fresh 12-hex nonce per call. An attacker
 * cannot close a fence whose token they cannot guess, whatever characters
 * survive sanitisation. That is also why the character policy above can afford
 * to keep U+FE0F and U+3164 -- the fence no longer depends on it.
 *
 * The caller MUST name [begin] and [end] in its instruction text instead of
 * hardcoding a marker, which is why this returns them rather than a bare string.
 */
export function fenceAsData(
  sanitised: string,
  label = "USER_DATA",
): FencedBlock {
  const nonce = crypto.randomUUID().replace(/-/g, "").slice(0, 12);
  const begin = "<<<BEGIN_" + label + "_" + nonce + ">>>";
  const end = "<<<END_" + label + "_" + nonce + ">>>";
  return { text: begin + "\n" + sanitised + "\n" + end, begin, end };
}

/**
 * Marks a value as DELIBERATELY unsanitised because the user is the principal.
 *
 * The chat channel is the one place raw user text belongs in a prompt: the
 * user's message IS the request. Sanitising it would corrupt legitimate
 * multi-line messages, strip emoji from "great session!", and buy nothing --
 * they are not escaping into someone else's instructions, they are writing
 * their own. What needs protecting is the SYSTEM prompt around it.
 *
 * This is an identity function on purpose. It exists so the coverage gate sees
 * an explicit decision IN CODE at the call site, rather than a prose exemption
 * in a list somewhere else -- the mechanism that previously let a wrong
 * justification silence a right detection (food_parser.ts, review round 2).
 */
export function asPrincipalMessage(userMessage: string): string {
  return userMessage;
}

/**
 * Marks a locally-assembled prompt as AUTHORED BY US, not user-derived.
 *
 * Companion to [asPrincipalMessage]. Some prompts are built from our own
 * constants and template text a few lines above the call site
 * (assess-body-composition's clinical prompt, morning-alert's tone wrapper).
 * They are safe, but a checker cannot tell that from the identifier alone.
 *
 * WHY THIS EXISTS RATHER THAN A CLEVERER CHECKER. The coverage gate first tried
 * to TRACE identifiers to their declarations. Five rounds of tuning later,
 * negative controls still showed false PASSes -- windows bleeding past
 * statements, `.exec()` matching the wrong declaration, semicolons inside
 * comments truncating a body. A regex taint-tracker over TypeScript is the
 * wrong tool, and a gate that cannot be trusted to fail is worse than none.
 *
 * So the contract became blunt and checkable: a prompt value must be VISIBLY
 * safe at the assignment. If it is authored, say so here. The cost is one
 * wrapper call; the benefit is a gate with no tracing left to get wrong.
 */
export function asAuthoredPrompt(authored: string): string {
  return authored;
}

/**
 * prediction_quota_switch — the ONE owner of the prediction-quota kill
 * switch's name and its "on" rule. Kept free of imports so founder-digest and
 * telegram-admin-bot can report the switch without bundling Gemini
 * (`prediction_handler.ts` imports `gemini.ts`).
 *
 * `DISABLE_PREDICTION_QUOTA=true` in the Edge Function secrets stops the
 * `prediction_daily` metering without a redeploy (see prediction_handler.ts).
 * Only the exact string "true" turns it on. Read on every call, never at
 * module load.
 */

export const PREDICTION_QUOTA_KILL_SWITCH_ENV = "DISABLE_PREDICTION_QUOTA";

/** Whether an env-var kill switch is on: exactly the string "true". */
export function envSwitchOn(name: string): boolean {
  return Deno.env.get(name) === "true";
}

export function predictionQuotaDisabled(): boolean {
  return envSwitchOn(PREDICTION_QUOTA_KILL_SWITCH_ENV);
}
